bio("jafar", [
 ("هُوَ جَعْفَرُ بْنُ أَبِي طَالِبٍ، ابْنُ عَمِّ رَسُولِ اللَّهِ ﷺ، وَأَخُو عَلِيٍّ.", "Er ist Dschaʿfar ibn Abi Talib, Cousin des Gesandten Allahs ﷺ und Bruder ʿAlis.", 1632),
 ("وَكَانَ أَكْبَرَ مِنْ عَلِيٍّ بِعَشْرِ سِنِينَ.", "Er war zehn Jahre älter als ʿAli.", 1632),
 ("هَاجَرَ إِلَى الْحَبَشَةِ، وَكَانَ هُوَ الَّذِي يُكَلِّمُ النَّجَاشِيَّ عَنِ الْمُسْلِمِينَ.", "Er wanderte nach Abessinien aus und war es, der für die Muslime mit dem Negus sprach.", 1641),
 ("ثُمَّ قَدِمَ الْمَدِينَةَ عِنْدَ فَتْحِ خَيْبَرَ، فَسُرَّ النَّبِيُّ ﷺ بِقُدُومِهِ كَثِيرًا.", "Dann kam er zur Zeit der Einnahme Khaybars nach Medina, und der Prophet ﷺ freute sich sehr über seine Ankunft.", 1632),
 ("وَأَمَّرَهُ النَّبِيُّ ﷺ عَلَى جَيْشِ مُؤْتَةَ، فَاسْتُشْهِدَ هُنَاكَ.", "Der Prophet ﷺ machte ihn zum Befehlshaber des Heeres von Muʾta, und dort fiel er als Märtyrer.", 1632),
 ("وَرَآهُ النَّبِيُّ ﷺ مَلَكًا يَطِيرُ فِي الْجَنَّةِ، وَلُقِّبَ بِذِي الْجَنَاحَيْنِ.", "Der Prophet ﷺ sah ihn als einen Engel, der im Paradies fliegt; er erhielt den Beinamen „der mit den zwei Flügeln“.", 1638),
], [
 ("athar", "وَقَدْ سُرَّ رَسُوْلُ اللهِ -ﷺ- كَثِيْرًا بِقُدُوْمِهِ، وَحَزِنَ -وَاللهِ- لِوَفَاتِهِ.", "Der Gesandte Allahs ﷺ freute sich sehr über seine Ankunft und trauerte – bei Allah – über seinen Tod. (adh-Dhahabi)", 1632),
 ("hadith", "رَأَيْتُ جَعْفَرَ بنَ أَبِي طَالِبٍ مَلَكًا فِي الجَنَّةِ", "Ich sah Dschaʿfar ibn Abi Talib als Engel im Paradies.", 1638, E),
])
bio("abu-hurayra", [
 ("هُوَ أَبُو هُرَيْرَةَ الدَّوْسِيُّ، صَاحِبُ رَسُولِ اللَّهِ ﷺ، وَسَيِّدُ الْحُفَّاظِ.", "Er ist Abu Hurayra ad-Dausi, Gefährte des Gesandten Allahs ﷺ und der Herr der Hadith-Bewahrer.", 2558),
 ("اخْتُلِفَ فِي اسْمِهِ، وَأَرْجَحُ الْأَقْوَالِ: عَبْدُ الرَّحْمَنِ بْنُ صَخْرٍ.", "Über seinen Namen gibt es viele Angaben; am stärksten ist: ʿAbd ar-Rahman ibn Sakhr.", 2558),
 ("قَدِمَ وَأَسْلَمَ فِي أَوَّلِ سَنَةِ سَبْعٍ، عَامَ خَيْبَرَ.", "Er kam und nahm den Islam an zu Beginn des Jahres 7, im Jahr von Khaybar.", 2566),
 ("كَانَ فَقِيرًا مِنْ أَهْلِ الصُّفَّةِ، يَلْزَمُ النَّبِيَّ ﷺ.", "Er war ein Armer der Suffa und blieb ständig beim Propheten ﷺ.", 2575),
 ("وَكَانَ يَحْضُرُ حِينَ يَغِيبُ النَّاسُ، وَيَحْفَظُ حِينَ يَنْسَوْنَ.", "Er war dabei, wenn andere fehlten, und behielt, wenn andere vergaßen.", 2575),
 ("بَسَطَ ثَوْبَهُ عِنْدَ النَّبِيِّ ﷺ، فَمَا نَسِيَ شَيْئًا سَمِعَهُ مِنْهُ بَعْدَ ذَلِكَ.", "Er breitete sein Gewand vor dem Propheten ﷺ aus, und danach vergaß er nichts mehr, was er von ihm hörte.", 2575),
], [
 ("athar", "سَيِّدُ الحُفَّاظِ الأَثْبَاتِ", "Der Herr der zuverlässigen Hadith-Bewahrer. (adh-Dhahabi)", 2558),
 ("athar", "فَوَالَّذِي بَعَثَهُ بِالحَقِّ، مَا نَسِيْتُ شَيْئًا سَمِعْتُهُ مِنْهُ", "Bei Dem, der ihn mit der Wahrheit gesandt hat: Ich habe nichts vergessen, was ich von ihm hörte. (Abu Hurayra)", 2575, E),
])
bio("ibn-abbas", [
 ("هُوَ عَبْدُ اللَّهِ بْنُ عَبَّاسٍ، ابْنُ عَمِّ رَسُولِ اللَّهِ ﷺ.", "Er ist ʿAbdullah ibn ʿAbbas, der Cousin des Gesandten Allahs ﷺ.", 2939),
 ("لُقِّبَ بِحَبْرِ الْأُمَّةِ، وَإِمَامِ التَّفْسِيرِ.", "Man nannte ihn den Gelehrten der Umma und den Imam der Quran-Auslegung.", 2939),
 ("وُلِدَ فِي شِعْبِ بَنِي هَاشِمٍ، قَبْلَ الْهِجْرَةِ بِثَلَاثِ سِنِينَ.", "Er wurde in der Schlucht der Banu Haschim geboren, drei Jahre vor der Hidschra.", 2940),
 ("وَكَانَ صَغِيرًا حِينَ تُوُفِّيَ النَّبِيُّ ﷺ، وَاخْتُلِفَ فِي سِنِّهِ يَوْمَئِذٍ.", "Er war noch jung, als der Prophet ﷺ starb; über sein damaliges Alter gibt es verschiedene Angaben.", 2943),
 ("دَعَا لَهُ النَّبِيُّ ﷺ: اللَّهُمَّ فَقِّهْهُ فِي الدِّينِ، وَعَلِّمْهُ التَّأْوِيلَ.", "Der Prophet ﷺ betete für ihn: O Allah, gib ihm Verständnis in der Religion und lehre ihn die Auslegung.", 2945),
 ("وَدَعَا لَهُ بِالْحِكْمَةِ مَرَّتَيْنِ.", "Und er bat zweimal für ihn um Weisheit.", 2947),
], [
 ("athar", "حَبْرُ الأُمَّةِ، وَفَقِيْهُ العَصْرِ، وَإِمَامُ التَّفْسِيْرِ", "Der Gelehrte der Umma, der Rechtsgelehrte seiner Zeit und der Imam der Quran-Auslegung. (adh-Dhahabi)", 2939),
 ("hadith", "اللَّهُمَّ فَقِّهْهُ فِي الدِّيْنِ، وَعَلِّمْهُ التَّأْوِيْلَ", "O Allah, gib ihm Verständnis in der Religion und lehre ihn die Auslegung.", 2945, E),
])
bio("muadh", [
 ("هُوَ مُعَاذُ بْنُ جَبَلٍ الْأَنْصَارِيُّ، مِنَ الْخَزْرَجِ، أَبُو عَبْدِ الرَّحْمَنِ.", "Er ist Muʿadh ibn Dschabal al-Ansari, aus dem Stamm Khazradsch, Abu ʿAbd ar-Rahman.", 1870),
 ("شَهِدَ الْعَقَبَةَ شَابًّا، ثُمَّ شَهِدَ بَدْرًا وَلَهُ نَحْوُ عِشْرِينَ سَنَةً.", "Er war als junger Mann bei ʿAqaba dabei und kämpfte dann mit etwa zwanzig Jahren bei Badr.", 1870),
 ("بَعَثَهُ النَّبِيُّ ﷺ إِلَى الْيَمَنِ.", "Der Prophet ﷺ sandte ihn in den Jemen.", 1874),
 ("وَخَرَجَ النَّبِيُّ ﷺ يُوصِيهِ، وَمُعَاذٌ رَاكِبٌ وَالنَّبِيُّ ﷺ يَمْشِي.", "Der Prophet ﷺ ging mit ihm hinaus, um ihm Ratschläge zu geben – Muʿadh ritt, und der Prophet ﷺ ging zu Fuß.", 1874),
 ("وَقَالَ لَهُ وَلِأَبِي مُوسَى: يَسِّرَا وَلَا تُعَسِّرَا.", "Er sagte zu ihm und zu Abu Musa: Macht es leicht und macht es nicht schwer.", 1875),
], [
 ("athar", "شَهِدَ العَقَبَةَ شَابًّا أَمْرَدَ", "Er war als bartloser junger Mann bei ʿAqaba dabei. (adh-Dhahabi)", 1870),
 ("hadith", "يَسِّرَا وَلاَ تُعَسِّرَا، وَتَطَاوَعَا وَلاَ تُنَفِّرَا", "Macht es leicht und nicht schwer, seid euch einig und schreckt nicht ab.", 1875, E),
])
bio("abu-dharr", [
 ("هُوَ أَبُو ذَرٍّ جُنْدُبُ بْنُ جُنَادَةَ الْغِفَارِيُّ.", "Er ist Abu Dharr Dschundub ibn Dschunada al-Ghifari.", 2026),
 ("كَانَ مِنَ السَّابِقِينَ الْأَوَّلِينَ، وَمِنْ نُجَبَاءِ الصَّحَابَةِ.", "Er gehörte zu den ersten Muslimen und zu den edelsten Gefährten.", 2026),
 ("لَمَّا جَاءَ مَكَّةَ لَمْ يَكُنْ لَهُ طَعَامٌ إِلَّا مَاءُ زَمْزَمَ.", "Als er nach Mekka kam, hatte er keine Nahrung außer Zamzam-Wasser.", 2031),
 ("ثُمَّ رَجَعَ إِلَى قَوْمِهِ بِأَمْرِ النَّبِيِّ ﷺ، فَلَمَّا هَاجَرَ النَّبِيُّ ﷺ هَاجَرَ إِلَيْهِ.", "Dann kehrte er auf Anweisung des Propheten ﷺ zu seinem Stamm zurück; als der Prophet ﷺ auswanderte, wanderte er zu ihm aus.", 2026),
 ("وَكَانَ يُفْتِي فِي خِلَافَةِ أَبِي بَكْرٍ وَعُمَرَ وَعُثْمَانَ.", "Er gab Rechtsauskünfte während des Kalifats von Abu Bakr, ʿUmar und ʿUthman.", 2026),
 ("وَخَرَجَ فِي آخِرِ حَيَاتِهِ إِلَى الرَّبَذَةِ، وَمَاتَ هُنَاكَ.", "Am Ende seines Lebens ging er nach ar-Rabadha und starb dort.", 2037),
], [
 ("athar", "أَحَدُ السَّابِقِيْنَ الأَوَّلِيْنَ، مِنْ نُجَبَاءِ أَصْحَابِ مُحَمَّدٍ -ﷺ-", "Einer der ersten Muslime, einer der edelsten Gefährten Muhammads ﷺ. (adh-Dhahabi)", 2026),
 ("athar", "مَا لِي طَعَامٌ إِلاَّ مَاءُ زَمْزَمَ", "Ich hatte keine Nahrung außer Zamzam-Wasser. (Abu Dharr)", 2031, E),
])
